// Shape the Error Trigger payload into something readable on a phone.
// Documented fields: workflow.{id,name}, execution.{id,url,error,lastNodeExecuted,mode,retryOf}.
// execution.id/url require executions to be saved in the DB, and are ABSENT when the failure
// is in the main workflow's trigger node — so treat every field as optional.
const d = $input.first().json || {};
const wf = d.workflow || {};
const ex = d.execution || {};
const err = ex.error || {};

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const node = ex.lastNodeExecuted || '(unknown node)';
let msg = err.message || err.description || 'no error message provided';

// Translate the failures we actually hit into a verdict + next action, so the alert says what
// to DO, not just what broke.
let hint = '';
const m = msg.toLowerCase();
if (m.includes('overloaded') || msg.includes('529')) {
  hint = 'Provider capacity (HTTP 529) — not a pipeline bug. Re-send the ticker.';
} else if (msg.includes('429') || m.includes('rate limit')) {
  hint = 'Rate limited. Wait a few minutes, then re-send the ticker.';
} else if (msg.includes('401') || msg.includes('403')) {
  hint = 'Auth rejected — check the credential for this node (expired key/secret?).';
} else if (m.includes('is not defined') || m.includes('cannot read')) {
  hint = 'Code defect in a node — send this message to Claude, do not re-run blindly.';
} else if (m.includes('timeout') || m.includes('etimedout')) {
  hint = 'Timeout — Railway may be cold-starting. Re-send once; if it repeats, check the service.';
} else if (m.includes('econnrefused') || m.includes('enotfound')) {
  hint = 'Microservice unreachable — is growth-enrich up? Is PYTHON_SERVICE_URL set?';
}

const lines = [
  '\u274C <b>Consilium run failed</b>',
  '',
  '<b>Workflow:</b> ' + esc(wf.name || 'unknown'),
  '<b>Failed at:</b> <code>' + esc(node) + '</code>',
  '<b>Error:</b> ' + esc(String(msg).slice(0, 400)),
];
if (hint) lines.push('', '\u27A1\uFE0F <b>' + esc(hint) + '</b>');
if (ex.url) lines.push('', '<a href="' + ex.url + '">Open execution in n8n</a>');
else if (ex.id) lines.push('', '<b>Execution id:</b> ' + esc(ex.id));
if (ex.retryOf) lines.push('<i>(this was a retry of ' + esc(ex.retryOf) + ')</i>');

return [{ json: {
  text: lines.join('\n'),
  chat_id: 'YOUR_TELEGRAM_CHAT_ID',   // not a secret; $env is unavailable in n8n 2.x Code nodes
  _node: node,
  _hint: hint,
} }];
